// ============================================================================
// OFFLINE-FIRST CANVAS CONFETTI ENGINE (vendor/confetti.browser.min.js)
// Hieu ung phao hoa chuc mung hoc sinh 9+3 chay 100% Offline khong can mang
// ============================================================================
(function(global) {
  if (global.confetti) return;
  global.confetti = function(opts) {
    try {
      var count = (opts && opts.particleCount) || 55;
      var canvas = document.createElement('canvas');
      canvas.style.cssText = 'position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:9999';
      document.body.appendChild(canvas);
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      var ctx = canvas.getContext('2d');
      var colors = ['#10b981', '#fbbf24', '#38bdf8', '#f43f5e', '#a855f7'];
      var particles = [];
      for (var i = 0; i < count; i++) {
        particles.push({
          x: canvas.width * 0.5,
          y: canvas.height * 0.55,
          vx: (Math.random() - 0.5) * 14,
          vy: (Math.random() - 0.85) * 14,
          size: 6 + Math.random() * 6,
          color: colors[i % colors.length],
          alpha: 1
        });
      }
      var frame = 0;
      function tick() {
        frame++;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        particles.forEach(function(p) {
          p.x += p.vx;
          p.y += p.vy;
          p.vy += 0.35;
          p.alpha = Math.max(0, 1 - frame / 65);
          ctx.globalAlpha = p.alpha;
          ctx.fillStyle = p.color;
          ctx.fillRect(p.x, p.y, p.size, p.size);
        });
        if (frame < 65) requestAnimationFrame(tick);
        else if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
      }
      requestAnimationFrame(tick);
    } catch (e) {}
  };
})(window);
